class DET_curve():

    def __init__(self, thresholds):
        self.thresholds = thresholds

    def compute_rates(self, match_data, nonmatch_data, thresholds):
        totalmatch = len(match_data)
        totalnonmatch = len(nonmatch_data)

        false_nonmatch_rates = []
        false_match_rates = []
        for th in thresholds:
            false_nonmatch = 0
            true_match = 0

            for m in match_data:
                if m < th:
                    # match is labeled nonmatch
                    false_nonmatch += 1
                if m > th:
                    # match is labeled match
                    true_match += 1
            
            false_nonmatch_rate = false_nonmatch / totalmatch * 100
            false_nonmatch_rates.append(false_nonmatch_rate)

            true_nonmatch = 0
            false_match = 0
            for nm in nonmatch_data:
                if nm < th:
                    # nonmatch is labeled nonmatch
                    true_nonmatch += 1
                if nm > th:
                    # nonmatch is labeled match
                    false_match += 1
            
            false_match_rate = false_match / totalnonmatch * 100
            false_match_rates.append(false_match_rate)

        return false_match_rates, false_nonmatch_rates, thresholds
    
    def draw_curve(self, fmr, fnmr):
        plt.plot(fmr, fnmr)
        plt.title("DET curve")
        plt.xlabel("FMR")
        plt.ylabel("FNMR")
        plt.show()
        return plt

    def __call__(self, matching_data, nonmatching_data):
        fmr, fnmr, _ = self.compute_rates(matching_data, nonmatching_data, self.thresholds)
        plt = self.draw_curve(fmr, fnmr)
        return plt


curve = DET_curve(np.arange(0.0,0.51,0.001))
curve(match,nomatch)

class Histogram():

    def draw_histogram(self, matching_data, nonmatching_data, guide):
        range = [0.0,0.5]
        
        plt.hist(matching_data, range=range, density=True, bins=60, alpha=0.5, color='blue', label='Matching')
        plt.hist(nonmatching_data, range=range, density=True, bins=60, alpha=0.5, color='red', label='Non-Matching')
        plt.title(f'Bundling Guide {guide}')
        plt.xlabel('Correlation Score')
        plt.ylabel('Normalized Frequency')
        # plt.ylim(0,35)
        plt.legend(loc='upper right')

        plt.show()
        return plt
    
    def __call__(self, matching_data, nonmatching_data, guide):
        plt = self.draw_histogram(matching_data, nonmatching_data, guide)
        return plt

hist = Histogram()
hist(match, nomatch, "V1")


